static void iterB_8(void){
  for(long x=0;x<8;x++){
    const size_t pb=(size_t)x*512;
    byP_8(BR_8+pb, BI_8+pb);
  }
  for(long y=0;y<8;y++){
    bcopyin_8(BR_8+(size_t)y*64, BI_8+(size_t)y*64, BQR_8, BQI_8);
    bxqP_8(BQR_8, BQI_8);
    bzP_8(BQR_8, BQI_8);
    bnormstore_8(BCR_8+(size_t)y*512, BCI_8+(size_t)y*512, BR_8+(size_t)y*64, BI_8+(size_t)y*64);
  }
}
static void bconvc_8(const double* cin, double*restrict vr, double*restrict vi, long vc){
  const double* s[8]; for(int v=0;v<8;v++) s[v]=cin+(size_t)(v<vc?v:vc-1)*1024;
  for(long x=0;x<8;x++)for(long y=0;y<8;y++){
    const size_t db=((size_t)y*8+x)*64; const size_t sb=2*((x*8+y)*8);
    long z=0;
    for(; z+4<=8; z+=4){
      __m512d m0=_mm512_loadu_pd(s[0]+sb+2*z), m1=_mm512_loadu_pd(s[1]+sb+2*z), m2=_mm512_loadu_pd(s[2]+sb+2*z), m3=_mm512_loadu_pd(s[3]+sb+2*z);
      __m512d m4=_mm512_loadu_pd(s[4]+sb+2*z), m5=_mm512_loadu_pd(s[5]+sb+2*z), m6=_mm512_loadu_pd(s[6]+sb+2*z), m7=_mm512_loadu_pd(s[7]+sb+2*z);
      VD c0,c1,c2,c3,c4,c5,c6,c7;
      TP8(c0,c1,c2,c3,c4,c5,c6,c7,(VD)m0,(VD)m1,(VD)m2,(VD)m3,(VD)m4,(VD)m5,(VD)m6,(VD)m7);
      vstore(vr+db+z*8,c0); vstore(vi+db+z*8,c1); vstore(vr+db+z*8+8,c2); vstore(vi+db+z*8+8,c3);
      vstore(vr+db+z*8+16,c4); vstore(vi+db+z*8+16,c5); vstore(vr+db+z*8+24,c6); vstore(vi+db+z*8+24,c7);
    }
    for(; z<8; z++) for(int v=0;v<8;v++){ vr[db+z*8+v]=s[v][sb+2*z]; vi[db+z*8+v]=s[v][sb+2*z+1]; }
  }
}
static void runB_8(const double* xin, const double* cin, double* o1, double* om, long m, long vc){
  bconvin_8(xin, BR_8, BI_8, vc);
  bconvc_8(cin, BCR_8, BCI_8, vc);
  if(m<=0){ bconvout_8(BR_8, BI_8, o1, vc); bconvout_8(BR_8, BI_8, om, vc); return; }
  for(long it=0; it<m; it++){
    iterB_8();
    if(it==0) bconvout_8(BR_8, BI_8, o1, vc);
  }
  bconvout_8(BR_8, BI_8, om, vc);
}
static void run_8(long B, long m, const double* xin, const double* cin, double* o1, double* om){
  long b=0;
  if(useB[1]){
    for(; b+8<=B; b+=8)
      runB_8(xin+(size_t)b*1024, cin+(size_t)b*1024, o1+(size_t)b*1024, om+(size_t)b*1024, m, 8);
    if(B-b >= 9){
      runB_8(xin+(size_t)b*1024, cin+(size_t)b*1024, o1+(size_t)b*1024, om+(size_t)b*1024, m, B-b);
      b = B;
    }
  }
  for(; b<B; b++)
    runT_8(xin+(size_t)b*1024, cin+(size_t)b*1024, o1+(size_t)b*1024, om+(size_t)b*1024, m);
}
