static void runB_45(const double* xin, const double* cin, double* o1, double* om, long m, long vc){
  bconvin_45(xin, BR_45, BI_45, vc);
  bconvc_45(cin, BCR_45, BCI_45, vc);
  if(m<=0){ bconvout_45(BR_45, BI_45, o1, vc); bconvout_45(BR_45, BI_45, om, vc); return; }
  for(long it=0; it<m; it++){
    iterB_45();
    if(it==0) bconvout_45(BR_45, BI_45, o1, vc);
  }
  bconvout_45(BR_45, BI_45, om, vc);
}
static void run_45(long B, long m, const double* xin, const double* cin, double* o1, double* om){
  long b=0;
  if(useB[6]){
    for(; b+8<=B; b+=8)
      runB_45(xin+(size_t)b*182250, cin+(size_t)b*182250, o1+(size_t)b*182250, om+(size_t)b*182250, m, 8);
    if(B-b >= 7){
      runB_45(xin+(size_t)b*182250, cin+(size_t)b*182250, o1+(size_t)b*182250, om+(size_t)b*182250, m, B-b);
      b = B;
    }
  }
  for(; b<B; b++)
    runT_45(xin+(size_t)b*182250, cin+(size_t)b*182250, o1+(size_t)b*182250, om+(size_t)b*182250, m);
}
