static double *XR_64,*XI_64,*CR_64,*CI_64,*PR_64,*PI_64,*QR_64,*QI_64,*Q2R_64,*Q2I_64;
static void copyin_64(const double*restrict vr, const double*restrict vi, double*restrict qr, double*restrict qi){
  for(long x=0;x<64;x++){
    const double* sr = vr + x*4608; const double* si = vi + x*4608;
    __builtin_prefetch(sr + 18432 + 0, 0, 3); __builtin_prefetch(si + 18432 + 0, 0, 3);
    __builtin_prefetch(sr + 18432 + 8, 0, 3); __builtin_prefetch(si + 18432 + 8, 0, 3);
    __builtin_prefetch(sr + 18432 + 16, 0, 3); __builtin_prefetch(si + 18432 + 16, 0, 3);
    __builtin_prefetch(sr + 18432 + 24, 0, 3); __builtin_prefetch(si + 18432 + 24, 0, 3);
    __builtin_prefetch(sr + 18432 + 32, 0, 3); __builtin_prefetch(si + 18432 + 32, 0, 3);
    __builtin_prefetch(sr + 18432 + 40, 0, 3); __builtin_prefetch(si + 18432 + 40, 0, 3);
    __builtin_prefetch(sr + 18432 + 48, 0, 3); __builtin_prefetch(si + 18432 + 48, 0, 3);
    __builtin_prefetch(sr + 18432 + 56, 0, 3); __builtin_prefetch(si + 18432 + 56, 0, 3);
    vstore(qr + x*72 + 0, vload(sr + 0)); vstore(qi + x*72 + 0, vload(si + 0));
    vstore(qr + x*72 + 8, vload(sr + 8)); vstore(qi + x*72 + 8, vload(si + 8));
    vstore(qr + x*72 + 16, vload(sr + 16)); vstore(qi + x*72 + 16, vload(si + 16));
    vstore(qr + x*72 + 24, vload(sr + 24)); vstore(qi + x*72 + 24, vload(si + 24));
    vstore(qr + x*72 + 32, vload(sr + 32)); vstore(qi + x*72 + 32, vload(si + 32));
    vstore(qr + x*72 + 40, vload(sr + 40)); vstore(qi + x*72 + 40, vload(si + 40));
    vstore(qr + x*72 + 48, vload(sr + 48)); vstore(qi + x*72 + 48, vload(si + 48));
    vstore(qr + x*72 + 56, vload(sr + 56)); vstore(qi + x*72 + 56, vload(si + 56));
  }
}
