    vstore(dr + 8, zr1*sc1); vstore(di + 8, zi1*sc1);
    vstore(dr + 16, zr2*sc2); vstore(di + 16, zi2*sc2);
    vstore(dr + 24, zr3*sc3); vstore(di + 24, zi3*sc3);
    vstore(dr + 32, zr4*sc4); vstore(di + 32, zi4*sc4);
    vstore(dr + 40, zr5*sc5); vstore(di + 40, zi5*sc5);
